import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def invoke_bedrock_model(
    prompt: str,
    model_id: str = "anthropic.claude-3-sonnet-20240229-v1:0",
    max_tokens: int = 256,
    temperature: float = 0.7,
    aws_region: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Invoke a provider-managed model on Amazon Bedrock using the boto3 Bedrock Runtime client.

    Returns a normalized dictionary containing the raw response and extracted text when available.
    """
    region = aws_region or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or "us-east-1"
    client = boto3.client("bedrock-runtime", region_name=region)

    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": max_tokens,
        "temperature": temperature,
        "messages": [
            {
                "role": "user",
                "content": [{"type": "text", "text": prompt}],
            }
        ],
    }

    try:
        response = client.invoke_model(
            modelId=model_id,
            body=bytes(__import__("json").dumps(body), "utf-8"),
            contentType="application/json",
            accept="application/json",
        )
        raw = response.get("body").read()
        payload = __import__("json").loads(raw)

        text = ""
        if isinstance(payload, dict):
            content = payload.get("content")
            if isinstance(content, list):
                parts = []
                for item in content:
                    if isinstance(item, dict) and item.get("type") == "text":
                        parts.append(item.get("text", ""))
                text = "".join(parts)
            elif "outputText" in payload:
                text = payload.get("outputText", "") or ""

        return {
            "provider": "amazon_bedrock",
            "model_id": model_id,
            "region": region,
            "text": text,
            "raw": payload,
        }
    except (BotoCoreError, ClientError) as exc:
        return {
            "provider": "amazon_bedrock",
            "model_id": model_id,
            "region": region,
            "error": str(exc),
        }
